fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 length mismatch");
    assert_eq!(conds_1.len(), n, "conds_1 length mismatch");
    assert_eq!(conds_2.len(), n, "conds_2 length mismatch");

    // Ensure output has the right length and can be overwritten.
    avgs.resize(n, 0);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        // Assumption states at least one is true; enforce to avoid undefined behavior.
        assert!(c1 || c2, "both conditions false at index {i}");

        let v1 = vals_1[i];
        let v2 = vals_2[i];

        // Assumption states values are < 1000; enforce (also makes sum safe).
        assert!(v1 < 1000, "vals_1[{i}] out of range");
        assert!(v2 < 1000, "vals_2[{i}] out of range");

        avgs[i] = match (c1, c2) {
            (true, true) => (v1 + v2) / 2,
            (true, false) => v1,
            (false, true) => v2,
            (false, false) => unreachable!(),
        };
    }
}